  "output_head": "<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title><%= content_for(:title) %> · Quizzy</title>
<%= csrf_meta_tags %>
<%= csp_meta_tag %>
<link rel="icon" href="/icon.svg" type="image/svg+xml">
<%= stylesheet_link_tag "quizzy", "application" %>
<!doctype html>
<html lang="en">
  <head>
    <%= render "layouts/head" %>
    <%= javascript_include_tag "moderate", defer: true %>
  </head>
  <body>
    <header class="admin-header">
      <%= link_to moderate_root_path, class: "logo admin-header__logo", aria: { label: "Quizzy · All quizzes" } do %>
        <span class="logo__mark" aria-hidden="true">?</span>Quizzy
      <% end %>
      <span class="admin-header__tag">Moderator</span>
    </header>
    <main class="admin-main"><%= yield %></main>
  </body>
</html>
<!doctype html>
<html lang="en">
  <head>
    <%= render "layouts/head" %>
    <%= javascript_include_tag "preview", defer: true %>
  </head>
  <body>
    <nav class="preview-banner" aria-label="Preview navigation">
      <span>Moderator preview</span>
      <%= link_to "Back to quiz", moderate_quiz_path(@quiz) %>
    </nav>
    <main class="play">
      <div class="play__top">
        <span class="logo play__logo"><span class="logo__mark" aria-hidden="true">?</span>Quizzy</span>
        <span><%= @quiz.title %></span>
      </div>
      <%= yield %>
    </main>
  </body>
</html>
<% content_for :title, @quiz.title %>
<div class="breadcrumbs"><%= link_to "← All quizzes", moderate_root_path %></div>
<div class="page-head">
  <div>
    <h1><%= @quiz.title %></h1>
    <div class="meta mt-2"><%= @questions.count(&:active?) %> of <%= pluralize(@questions.size, "question") %> active · <%= link_to "Settings", edit_moderate_quiz_path(@quiz) %></div>
  </div>
  <div class="buttons">
    <%= link_to "Export", export_moderate_quiz_path(@quiz), class: "btn btn--ghost" %>
    <%= link_to "Preview", preview_moderate_quiz_path(@quiz), class: "btn btn--ghost" %>
  </div>
</div>
<section class="section mt-0" aria-labelledby="questions-title">
  <div class="section-head">
    <h2 id="questions-title">Questions</h2>
    <%= link_to "Add question", new_moderate_quiz_question_path(@quiz), class: "btn" %>
  </div>
  <% if @questions.empty? %>
    <div class="empty">No questions yet. Add the first question to your quiz.</div>
  <% else %>
    <ol class="question-list">
      <% active_number = 0 %>
      <% @questions.each_with_index do |question, index| %>
        <% number = question.active? ? (active_number += 1) : "—" %>
        <%= render "question", question: question, number: number, first: index.zero?, last: index == @questions.size - 1 %>
      <% end %>
    </ol>
  <% end %>
</section>
<% content_for :title, "Preview · #{@quiz.title}" %>
<% if @questions.empty? %>
  <div class="empty">No active questions to preview.</div>
<% else %>
  <div class="play__body play__body--top" data-preview-screen>
    <noscript>Enable JavaScript to play the preview.</noscript>
  </div>
  <% @questions.each_with_index do |question, index| %>
    <template data-preview-question>
      <div class="play-question__num">Question <%= index + 1 %> of <%= @questions.size %></div>
      <h1 class="play-question__body" tabindex="-1"><%= question.body %></h1>
      <div class="play-options">
        <% each_lettered_option(question) do |letter, option| %>
          <button type="button" class="play-option" data-correct="<%= option['correct'] %>">
            <span class="play-option__letter" aria-hidden="true"><%= letter %></span>
            <span class="play-option__title"><%= option['text'] %></span>
            <% if option['correct'] %><span class="play-option__mark" hidden>✓ Correct</span><% end %>
          </button>
        <% end %>
      </div>
      <div class="play-status" role="status" hidden></div>
      <button type="button" class="btn btn--pink preview-next" hidden><%= index == @questions.size - 1 ? "See score" : "Next question" %></button>
    </template>
  <% end %>
  <template data-preview-result>
    <div class="card result-card">
      <p class="field-label">Preview complete</p>
      <h1 class="result-card__score" tabindex="-1"></h1>
      <div class="buttons"><button type="button" class="btn btn--pink" data-restart>Start over</button></div>
    </div>
  </template>
<% end %>
<% content_for :title, "Quizzes" %>
<div class="page-head">
  <h1>Quizzes</h1>
  <div class="buttons">
    <%= button_to "Import quiz", import_moderate_quizzes_path, method: :get, class: "btn btn--ghost" %>
    <%= link_to "New quiz", new_moderate_quiz_path, class: "btn btn--pink" %>
  </div>
</div>
<% if @quizzes.empty? %>
  <div class="empty">No quizzes yet. Create a quiz to start adding questions.</div>
<% else %>
  <ul class="quiz-list" aria-label="Quizzes">
    <% @quizzes.each do |quiz| %>
      <li>
        <%= link_to moderate_quiz_path(quiz), class: "card quiz-tile", aria: { label: quiz.title } do %>
          <h2><%= quiz.title %></h2>
          <div ",
  "output_tail": "ard .question-item__body a { text-decoration: none; }
.question-item__options li.is-picked { box-shadow: inset 0 0 0 2px var(--c-pink); }
.question-item__options li.is-picked.is-correct { box-shadow: none; }
.question-item__options li.is-picked::after { content: " · participant's answer"; font-weight: 600; }

.pager { display: flex; flex-wrap: wrap; gap: 12px; justify-content: space-between; margin-top: 24px; }

/* ---------- Quizzy additions ---------- */

.field-label { font-weight: 600; font-size: 15px; }

.quiz-list { list-style: none; padding: 0; margin: 0; }
.question-list { list-style: none; padding: 0; margin: 0; }

.input--code, .code-block { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 15px; }
.code-block { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; }

.result-card__prefix { font-size: 0.35em; display: block; letter-spacing: 0; }

.screen__kicker { font-weight: 700; font-size: clamp(18px, 1.8vw, 30px); opacity: 0.8; margin-bottom: 0.4em; }


.stage-option__mark {
  border-radius: 1000px;
  padding: 0.2em 0.7em;
  background: var(--c-success);
  color: var(--c-white);
  font-size: 0.55em;
  font-weight: 800;
}

.leader__badge {
  display: inline-block;
  margin-left: 0.4em;
  border-radius: 1000px;
  padding: 0.15em 0.6em;
  background: var(--c-pink);
  color: var(--c-white);
  font-size: 0.55em;
  vertical-align: middle;
}
.leader.is-winner .leader__name::after { content: none; }
// Use ordinary form submissions so changes go through Rails' CSRF protection.
for (const form of document.querySelectorAll('form[data-confirm]')) {
  form.addEventListener('submit', event => {
    if (!window.confirm(form.dataset.confirm)) event.preventDefault();
  });
}
for (const checkbox of document.querySelectorAll('[data-auto-submit]')) {
  checkbox.addEventListener('change', () => checkbox.form.requestSubmit());
}

const editor = document.querySelector('[data-question-editor]');
if (editor) {
  const rows = editor.querySelector('.option-rows');
  function numberRows() {
    Array.from(rows.children).forEach((row, index) => {
      const label = `Option ${index + 1}`;
      const text = row.querySelector('input[type=text]');
      text.placeholder = label;
      text.setAttribute('aria-label', label);
      row.querySelector('input[type=checkbox]').setAttribute('aria-label', `${label} is correct`);
      row.querySelector('[data-remove-option]').setAttribute('aria-label', `Remove option ${index + 1}`);
    });
  }

  editor.querySelector('[data-add-option]').addEventListener('click', () => {
    rows.append(editor.querySelector('template').content.cloneNode(true));
    numberRows();
    rows.lastElementChild.querySelector('input').focus();
  });
  rows.addEventListener('click', event => {
    const remove = event.target.closest('[data-remove-option]');
    if (remove) {
      remove.closest('.option-row').remove();
      numberRows();
    }
  });
}
// A dry run is entirely local to this page. Discard each question's choices
// on advance; the running total never leaves this script.
const screenBody = document.querySelector('[data-preview-screen]');
if (screenBody) {
  const questions = document.querySelectorAll('template[data-preview-question]');
  let index = 0;
  let score = 0;

  function showQuestion() {
    screenBody.replaceChildren(questions[index].content.cloneNode(true));
    const choices = screenBody.querySelector('.play-options');
    const feedback = screenBody.querySelector('.play-status');
    const next = screenBody.querySelector('.preview-next');

    choices.addEventListener('click', event => {
      const pick = event.target.closest('button');
      if (!pick || pick.disabled) return;
      const right = pick.dataset.correct === 'true';
      if (right) score++;
      pick.classList.add('is-picked');
      choices.classList.add('is-locked', 'is-revealed');
      for (const option of choices.querySelectorAll('button')) {
        option.disabled = true;
        if (option.dataset.correct === 'true') {
          option.classList.add('is-correct');
          option.querySelector('.play-option__mark').hidden = false;
        }
      }
      feedback.hidden = false;
      feedback.classList.add(right ? 'play-status--right' : 'play-status--wrong');
      feedback.textContent = right ? 'Correct!' : 'Wrong!';
      next.hidden = false;
    });

    next.addEventListener('click', () => {
      index++;
      if (index === questions.length) showResult();
      else showQuestion();
      screenBody.querySelector('h1').focus();
    });
  }

  function showResult() {
    screenBody.replaceChildren(document.querySelector('[data-preview-result]').content.cloneNode(true));
    screenBody.querySelector('h1').textContent = `Score: ${score}/${questions.length}`;
    screenBody.querySelector('[data-restart]').addEventListener('click', () => {
      index = 0;
      score = 0;
      showQuestion();
      screenBody.querySelector('h1').focus();
    });
  }

  showQuestion();
}
