[hidden] { display: none !important; }
:focus-visible { outline: 3px solid var(--c-night); outline-offset: 3px; }
.admin-main, .play { overflow-wrap: anywhere; }
.question-item__actions > form { display: flex; }
.field .checkbox { align-self: flex-start; font-size: 18px; font-weight: 500; }
.add-option { margin-bottom: 28px; }
.danger-zone { border-top: 2px solid var(--c-lavender); margin-top: 28px; padding-top: 20px; }
.quiz-tile { height: 100%; margin-bottom: 0; }
.quiz-tile h2 { font-size: clamp(22px, 2.2vw, 28px); }
.quiz-list { grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr)); }
.preview-banner + .play { min-height: calc(100dvh - 42px); }
.play__top > :last-child { text-align: right; }
.preview-next { margin-top: 16px; }
.result-card .buttons { justify-content: center; }
@media (max-width: 650px) {
  .question-item { grid-template-columns: auto minmax(0, 1fr); gap: 12px; }
  .question-item__num { min-width: 1em; }
  .question-item__actions { grid-column: 1 / -1; flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: space-between; }
  .card { padding: 18px; }
  .option-row { grid-template-columns: minmax(0, 1fr) auto auto; gap: 8px; }
}
/* ---------- Big screen (moderator presentation) ---------- */

.screen {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  padding: clamp(20px, 3vw, 56px);
  padding-bottom: 110px;
}

.screen__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(18px, 1.8vw, 30px);
}

.screen__logo { font-size: clamp(28px, 3vw, 52px); }

.screen__body { flex: 1; display: flex; flex-direction: column; justify-content: center; }

.screen-controls {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 50;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 16px clamp(20px, 3vw, 56px);
  padding-bottom: calc(16px + env(safe-area-inset-bottom, 0px));
  background: rgb(0 0 51 / 0.85);
  backdrop-filter: blur(8px);
  color: var(--c-lavender);
  font-size: 16px;
}
.screen-controls a { color: var(--c-lavender); }
.screen-controls__info { display: flex; gap: 24px; align-items: center; flex-wrap: wrap; }

/* Lobby */

.lobby { display: grid; grid-template-columns: 1fr auto; gap: clamp(24px, 4vw, 80px); align-items: center; }

.lobby__title {
  font-size: clamp(48px, 7vw, 140px);
  line-height: 0.9;
  margin-bottom: 0.3em;
  overflow-wrap: anywhere;
}

.lobby__join { font-size: clamp(20px, 2.2vw, 40px); font-weight: 600; margin-bottom: 0.3em; }
.lobby__url { font-family: var(--f-display); font-weight: 800; font-size: clamp(28px, 3.6vw, 72px); line-height: 1; overflow-wrap: anywhere; }

.qr {
  background: var(--c-white);
  border-radius: clamp(16px, 2vw, 32px);
  padding: clamp(12px, 1.4vw, 28px);
  width: min(62vh, 42vw);
  aspect-ratio: 1;
  box-shadow: 0 30px 80px rgb(0 0 51 / 0.35);
}
.qr svg { width: 100%; height: 100%; display: block; }

.counter-pill {
  display: inline-flex;
  align-items: baseline;
  gap: 0.4em;
  margin-top: 1.2em;
  padding: 0.4em 0.9em;
  border-radius: 1000px;
  background: rgb(221 221 255 / 0.18);
  font-size: clamp(18px, 1.8vw, 30px);
  font-weight: 600;
}
.counter-pill strong { font-family: var(--f-display); font-weight: 900; font-size: 1.3em; }

@media (max-width: 800px) {
  .lobby { grid-template-columns: 1fr; }
  .qr { width: min(80vw, 420px); }
}

/* Question on the big screen */

.stage-question__num { font-family: var(--f-display); font-weight: 800; font-size: clamp(20px, 2vw, 36px); opacity: 0.8; margin-bottom: 0.6em; }

.stage-question__body {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(32px, 4.4vw, 88px);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin-bottom: clamp(24px, 3vw, 56px);
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.stage-options {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr));
  gap: clamp(12px, 1.4vw, 24px);
}

.stage-option {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.8em;
  overflow: hidden;
  background: var(--c-lavender);
  color: var(--c-blue);
  border-radius: clamp(14px, 1.4vw, 24px);
  padding: 0.8em 1em;
  font-size: clamp(20px, 2.2vw, 40px);
  font-weight: 600;
  line-height: 1.15;
  isolation: isolate;
  transition: opacity 0.3s, transform 0.3s;
}

.stage-option__letter {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 1.8em;
  height: 1.8em;
  border-radius: 50%;
  background: var(--c-blue);
  color: var(--c-lavender);
  font-family: var(--f-display);
  font-weight: 900;
  font-size: 0.85em;
}

.stage-option__title { flex: 1; overflow-wrap: anywhere; }
